/* auto-generated by NAPI-RS, modified to load from dist/ */

const { existsSync, readFileSync } = require('fs')
const { join } = require("path");

const { platform, arch } = process;

let nativeBinding = null;
let localFileExisted = false;
let loadError = null;

const distDir = join(__dirname, "dist");

function isMusl() {
  if (!process.report || typeof process.report.getReport !== "function") {
    try {
      const lddPath = require("child_process").execSync("which ldd").toString().trim();
      return readFileSync(lddPath, "utf8").includes("musl");
    } catch (e) {
      return true;
    }
  } else {
    const { glibcVersionRuntime } = process.report.getReport().header;
    return !glibcVersionRuntime;
  }
}

function tryLoad(file) {
  const localPath = join(distDir, file);
  localFileExisted = existsSync(localPath);
  if (localFileExisted) {
    nativeBinding = require(localPath);
  }
}

switch (platform) {
  case "win32":
    switch (arch) {
      case "x64":
        tryLoad("verter-native.win32-x64-msvc.node");
        break;
      case "ia32":
        tryLoad("verter-native.win32-ia32-msvc.node");
        break;
      case "arm64":
        tryLoad("verter-native.win32-arm64-msvc.node");
        break;
      default:
        throw new Error(`Unsupported architecture on Windows: ${arch}`);
    }
    break;
  case "darwin":
    tryLoad("verter-native.darwin-universal.node");
    if (!nativeBinding) {
      switch (arch) {
        case "x64":
          tryLoad("verter-native.darwin-x64.node");
          break;
        case "arm64":
          tryLoad("verter-native.darwin-arm64.node");
          break;
        default:
          throw new Error(`Unsupported architecture on macOS: ${arch}`);
      }
    }
    break;
  case "linux":
    switch (arch) {
      case "x64":
        if (isMusl()) {
          tryLoad("verter-native.linux-x64-musl.node");
        } else {
          tryLoad("verter-native.linux-x64-gnu.node");
        }
        break;
      case "arm64":
        if (isMusl()) {
          tryLoad("verter-native.linux-arm64-musl.node");
        } else {
          tryLoad("verter-native.linux-arm64-gnu.node");
        }
        break;
      default:
        throw new Error(`Unsupported architecture on Linux: ${arch}`);
    }
    break;
  default:
    throw new Error(`Unsupported OS: ${platform}, architecture: ${arch}`);
}

if (!nativeBinding) {
  if (loadError) {
    throw loadError;
  }
  throw new Error(`Failed to load native binding`);
}

const { compile, compileForVite, processStyle } = nativeBinding;

module.exports.compile = compile;
module.exports.compileForVite = compileForVite;
module.exports.processStyle = processStyle;
